    M = 52
    S = N**2
    M2 = M**2

    h = []
    for r in range(1, N + 1):
        if r < M:
            h.append(r)
        elif r <= N - M + 1:
            h.append(M)
        else:
            h.append(N - r + 1)

    h_counts = {}
    for val in h:
        h_counts[val] = h_counts.get(val, 0) + 1

    unique_h = sorted(h_counts.keys())
    S_j = {}
    for j in range(1, M2 + 1):
        count = 0
        for v1 in unique_h:
            for v2 in unique_h:
                if v1 * v2 >= j:
                    count += h_counts[v1] * h_counts[v2]
        S_j[j] = count

    best_k = 0
    for t in range(1, 2000):
        t_M2 = t * M2
        D = t_M2 - S

        if D <= 0:
            for j in range(1, M2 + 1):
                k = min(S_j[j], t_M2 // j)
                best_k = max(best_k, k)
